"use client";

import { FormEvent, useEffect, useState } from "react";
import { useRouter } from "next/navigation";
import { Banknote, BarChart3, Bell, CalendarDays, CheckCircle2, ChevronDown, ChevronRight, FileText, LayoutDashboard, LogOut, Menu, MessageCircle, PackageOpen, Pencil, Plus, ReceiptText, Search, Sparkles, Stethoscope, Trash2, TrendingDown, TrendingUp, UserPlus, Users, WalletCards, X } from "lucide-react";
import { toast } from "sonner";
import { Toaster } from "@/components/ui/sonner";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Progress } from "@/components/ui/progress";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { NativeSelect, NativeSelectOption } from "@/components/ui/native-select";
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from "@/components/ui/dialog";

type Patient = { id: number; name: string; phone: string; email: string; notes: string; active: boolean; createdAt: string };
type ClinicPackage = { id: number; patientId: number; name: string; totalSessions: number; totalAmountCents: number; paidAmountCents: number; paymentMethod: string; paymentStatus: string; purchasedAt: string; lastPaymentAt: string | null; status: string };
type Session = { id: number; patientId: number; packageId: number; performedAt: string; procedureType: string; measurementIn: string; measurementOut: string; occurrences: string; notes: string };
type Payment = { id: number; patientId: number; packageId: number; amountCents: number; method: string; paidAt: string; notes: string };
type Appointment = { id: number; patientId: number; scheduledAt: string; durationMinutes: number; status: string; notes: string };
type Expense = { id: number; description: string; category: string; amountCents: number; paidAt: string; notes: string };
type ClinicData = { patients: Patient[]; packages: ClinicPackage[]; sessions: Session[]; payments: Payment[]; appointments: Appointment[]; expenses: Expense[] };
type View = "overview" | "patients" | "record" | "packages" | "sessions" | "payments" | "agenda";
type RecordTab = "summary" | "sessions" | "packages" | "payments" | "notes";
type Modal = "patient" | "patientEdit" | "package" | "session" | "payment" | "appointment" | "expense" | null;
type DeleteTarget = { action: string; id: number; label: string } | null;

const today = new Date().toISOString().slice(0, 10);
const demo: ClinicData = {
  patients: [
    { id: 1, name: "Mariana Souza", phone: "(11) 98765-4321", email: "mariana@email.com", notes: "Fisioterapia ortopédica", active: true, createdAt: "2026-09-18" },
    { id: 2, name: "Lucas Oliveira", phone: "(11) 99812-4477", email: "lucas@email.com", notes: "Pilates terapêutico", active: true, createdAt: "2026-09-12" },
    { id: 3, name: "Camila Martins", phone: "(11) 97654-1108", email: "camila@email.com", notes: "Fisioterapia preventiva", active: true, createdAt: "2026-09-10" },
    { id: 4, name: "Rafael Lima", phone: "(11) 96543-8890", email: "rafael@email.com", notes: "Reabilitação esportiva", active: true, createdAt: "2026-09-08" },
  ],
  packages: [
    { id: 1, patientId: 1, name: "Pacote de 5 sessões", totalSessions: 5, totalAmountCents: 75000, paidAmountCents: 75000, paymentMethod: "Pix", paymentStatus: "Pago", purchasedAt: "2026-09-18", lastPaymentAt: "2026-09-18", status: "Em andamento" },
    { id: 2, patientId: 2, name: "Pacote de 10 sessões", totalSessions: 10, totalAmountCents: 130000, paidAmountCents: 65000, paymentMethod: "Cartão", paymentStatus: "Parcial", purchasedAt: "2026-09-12", lastPaymentAt: "2026-09-12", status: "Em andamento" },
    { id: 3, patientId: 3, name: "Pacote de 8 sessões", totalSessions: 8, totalAmountCents: 112000, paidAmountCents: 112000, paymentMethod: "Pix", paymentStatus: "Pago", purchasedAt: "2026-09-10", lastPaymentAt: "2026-09-10", status: "Em andamento" },
    { id: 4, patientId: 4, name: "Pacote de 5 sessões", totalSessions: 5, totalAmountCents: 70000, paidAmountCents: 70000, paymentMethod: "Dinheiro", paymentStatus: "Pago", purchasedAt: "2026-09-08", lastPaymentAt: "2026-09-08", status: "Em andamento" },
  ],
  sessions: [...Array.from({ length: 3 }, (_, i) => ({ id: i + 1, patientId: 1, packageId: 1, performedAt: `2026-09-${18 - i}`, procedureType: "Fisioterapia", measurementIn: "", measurementOut: "", occurrences: "", notes: "" })), ...Array.from({ length: 6 }, (_, i) => ({ id: i + 10, patientId: 2, packageId: 2, performedAt: `2026-09-${18 - i}`, procedureType: "Pilates terapêutico", measurementIn: "", measurementOut: "", occurrences: "", notes: "" })), ...Array.from({ length: 7 }, (_, i) => ({ id: i + 20, patientId: 3, packageId: 3, performedAt: `2026-09-${18 - i}`, procedureType: "Fisioterapia", measurementIn: "", measurementOut: "", occurrences: "", notes: "" })), ...Array.from({ length: 4 }, (_, i) => ({ id: i + 30, patientId: 4, packageId: 4, performedAt: `2026-09-${18 - i}`, procedureType: "Reabilitação", measurementIn: "", measurementOut: "", occurrences: "", notes: "" }))],
  payments: [{ id: 1, patientId: 1, packageId: 1, amountCents: 75000, method: "Pix", paidAt: "2026-09-18", notes: "Pagamento integral" }, { id: 2, patientId: 2, packageId: 2, amountCents: 65000, method: "Cartão", paidAt: "2026-09-12", notes: "Primeira parcela" }, { id: 3, patientId: 3, packageId: 3, amountCents: 112000, method: "Pix", paidAt: "2026-09-10", notes: "Pagamento integral" }],
  appointments: [{ id: 1, patientId: 1, scheduledAt: `${today}T09:00`, durationMinutes: 50, status: "Agendado", notes: "" }, { id: 2, patientId: 2, scheduledAt: `${today}T10:30`, durationMinutes: 50, status: "Agendado", notes: "" }, { id: 3, patientId: 3, scheduledAt: `${today}T14:00`, durationMinutes: 50, status: "Agendado", notes: "" }],
  expenses: [],
};
const nav = [["overview", "Visão geral", LayoutDashboard], ["patients", "Pacientes", Users], ["packages", "Pacotes", PackageOpen], ["sessions", "Sessões", FileText], ["payments", "Financeiro", WalletCards], ["agenda", "Agenda", CalendarDays]] as const;
const money = (value: number) => new Intl.NumberFormat("pt-BR", { style: "currency", currency: "BRL" }).format(value / 100);
const dateBR = (value?: string | null) => value ? new Intl.DateTimeFormat("pt-BR", { timeZone: "UTC" }).format(new Date(`${value.slice(0, 10)}T12:00:00Z`)) : "—";
const initials = (name: string) => name.split(" ").slice(0, 2).map((part) => part[0]).join("");

export default function ClinicDashboard() {
  const router = useRouter();
  const [data, setData] = useState(demo); const [view, setView] = useState<View>("overview"); const [modal, setModal] = useState<Modal>(null);
  const [query, setQuery] = useState(""); const [selectedId, setSelectedId] = useState(1); const [recordTab, setRecordTab] = useState<RecordTab>("summary"); const [menu, setMenu] = useState(false); const [saving, setSaving] = useState(false); const [connected, setConnected] = useState(false); const [deleteTarget, setDeleteTarget] = useState<DeleteTarget>(null); const [editingPatient, setEditingPatient] = useState<Patient | null>(null);
  useEffect(() => { fetch("/api/clinic").then(async (r) => { if (!r.ok) throw new Error(); const result = await r.json() as ClinicData; setData(result); setConnected(true); }).catch(() => setConnected(false)); }, []);
  const name = (id: number) => data.patients.find((p) => p.id === id)?.name || "Paciente";
  const used = (id: number) => data.sessions.filter((s) => s.packageId === id).length;
  const remaining = (pkg: ClinicPackage) => Math.max(0, pkg.totalSessions - used(pkg.id));
  const filtered = data.patients.filter((p) => `${p.name} ${p.phone} ${p.email}`.toLowerCase().includes(query.toLowerCase()));
  const selected = data.patients.find((p) => p.id === selectedId) || data.patients[0];
  const selectedPackage = data.packages.find((p) => p.patientId === selected?.id && p.status !== "Concluído") || data.packages.find((p) => p.patientId === selected?.id);
  const pending = data.packages.filter((p) => p.paymentStatus !== "Pago").length;
  async function submit(event: FormEvent<HTMLFormElement>, action: string) { event.preventDefault(); setSaving(true); try { const values = Object.fromEntries(new FormData(event.currentTarget).entries()); const response = await fetch("/api/clinic", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ action, ...values }) }); const result = await response.json() as ClinicData & { error?: string }; if (!response.ok) throw new Error(result.error); setData(result); setConnected(true); setModal(null); toast.success("Registro salvo com sucesso."); } catch (e) { toast.error(e instanceof Error ? e.message : "Não foi possível salvar."); } finally { setSaving(false); } }
  async function mutate(action: string, payload: Record<string, unknown>, message: string) { setSaving(true); try { const response = await fetch("/api/clinic", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ action, ...payload }) }); const result = await response.json() as ClinicData & { error?: string }; if (!response.ok) throw new Error(result.error); setData(result); setConnected(true); setDeleteTarget(null); toast.success(message); } catch (e) { toast.error(e instanceof Error ? e.message : "Não foi possível concluir."); } finally { setSaving(false); } }
  const edit = (patient: Patient) => { setEditingPatient(patient); setModal("patientEdit"); };
  const logout = async () => { await fetch("/api/auth/logout", { method: "POST" }); router.replace("/login"); router.refresh(); };
  const go = (next: View) => { setView(next); setMenu(false); };
  const openRecord = (id: number) => { setSelectedId(id); setRecordTab("summary"); setView("record"); setQuery(""); };
  return <div className="min-h-screen bg-[#f6f8f6] text-[#17231f]"><Toaster position="top-right" richColors />
    <aside className={`fixed inset-y-0 left-0 z-40 w-[248px] bg-[#07533f] text-white transition-transform lg:translate-x-0 ${menu ? "translate-x-0" : "-translate-x-full"}`}><div className="flex h-full flex-col"><div className="flex items-center justify-between px-6 pb-8 pt-7"><button onClick={() => go("overview")} className="flex items-center gap-3 text-left"><span className="grid size-11 place-items-center rounded-2xl border border-white/20 bg-white/10"><Sparkles className="text-[#d9c58d]" /></span><span><strong className="block font-serif text-xl leading-5">Clínica Essência</strong><small className="text-white/60">Cuidado em cada sessão</small></span></button><button className="lg:hidden" onClick={() => setMenu(false)}><X /></button></div><nav className="space-y-1 px-3">{nav.map(([key, label, Icon]) => <button key={key} onClick={() => go(key)} className={`flex w-full items-center gap-3 rounded-xl px-4 py-3 text-left text-[15px] ${view === key ? "bg-white/15" : "text-white/70 hover:bg-white/10 hover:text-white"}`}><Icon className="size-5" />{label}</button>)}</nav><div className="mt-auto p-5"><div className="rounded-2xl border border-white/10 bg-white/10 p-4 text-sm"><div className="flex items-center gap-2 font-medium"><span className={`size-2 rounded-full ${connected ? "bg-emerald-300" : "bg-amber-300"}`} />{connected ? "Dados sincronizados" : "Modo demonstração"}</div><p className="mt-2 text-xs leading-relaxed text-white/55">Pacientes, pacotes e pagamentos protegidos em um só lugar.</p></div></div></div></aside>
    <main className="min-h-screen lg:pl-[248px]"><header className="sticky top-0 z-30 flex h-[74px] items-center gap-4 border-b border-[#dfe6e1] bg-white/90 px-4 backdrop-blur-xl sm:px-7"><Button variant="ghost" size="icon" className="lg:hidden" onClick={() => setMenu(true)}><Menu /></Button><div className="relative max-w-xl flex-1"><Search className="absolute left-3 top-1/2 size-4 -translate-y-1/2 text-[#718078]" /><Input value={query} onChange={(e) => { setQuery(e.target.value); setView("patients"); }} placeholder="Buscar pacientes, telefone ou e-mail..." className="h-11 rounded-xl bg-[#f6f8f6] pl-10" /></div><Button variant="ghost" size="icon" className="relative rounded-full"><Bell className="size-5" /><span className="absolute right-2 top-2 size-2 rounded-full bg-[#d69a42]" /></Button><div className="hidden items-center gap-3 border-l pl-5 sm:flex"><Avatar name="Maria Carolini" /><div><p className="text-sm font-semibold">Dra. Maria Carolini</p><p className="text-xs text-[#758078]">Fisioterapeuta</p></div></div><Button variant="ghost" size="icon" onClick={logout} title="Sair do sistema"><LogOut className="size-5" /></Button></header>
      <div className="mx-auto max-w-[1500px] p-4 sm:p-7 lg:p-9"><div className="mb-7 flex flex-wrap items-end justify-between gap-4"><div><p className="mb-1 text-sm font-medium text-[#608174]">Clínica Essência</p><h1 className="font-serif text-3xl font-semibold sm:text-4xl">{view === "record" ? "Prontuário do paciente" : nav.find(([key]) => key === view)?.[1]}</h1><p className="mt-1 text-sm text-[#758078]">{view === "record" ? "Sessões, pacotes, pagamentos e evolução em um só lugar." : "Informações atualizadas para uma rotina mais tranquila."}</p></div><div className="flex flex-wrap gap-2">{view === "agenda" && <Button variant="outline" onClick={() => setModal("appointment")}><CalendarDays /> Agendar</Button>}<Button variant="outline" onClick={() => setModal("package")}><PackageOpen /> Novo pacote</Button><Button className="bg-[#08684e] hover:bg-[#07533f]" onClick={() => setModal("patient")}><UserPlus /> Novo paciente</Button></div></div>
        {view === "overview" && <><section className="mb-6 grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Stat icon={Users} label="Pacientes ativos" value={data.patients.length} /><Stat icon={FileText} label="Sessões em haver" value={data.packages.reduce((sum, p) => sum + remaining(p), 0)} /><Stat icon={WalletCards} label="Pagamentos pendentes" value={pending} warning /><Stat icon={CalendarDays} label="Sessões hoje" value={data.appointments.filter((a) => a.scheduledAt.slice(0, 10) === today).length} /></section><section className="grid gap-6 xl:grid-cols-[1.65fr_.75fr]"><PatientTable patients={data.patients} packages={data.packages} used={used} remaining={remaining} selectedId={selectedId} onSelect={setSelectedId} /><PatientCard patient={selected} pkg={selectedPackage} used={used} remaining={remaining} onOpen={(p) => openRecord(p.id)} onEdit={edit} onDelete={(p) => setDeleteTarget({ action: "patient.delete", id: p.id, label: p.name })} /></section></>}
        {view === "patients" && <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{filtered.map((p) => { const pkg = data.packages.find((item) => item.patientId === p.id); return <button key={p.id} onClick={() => openRecord(p.id)} className="premium-card rounded-[22px] border bg-white p-5 text-left shadow-sm transition hover:-translate-y-0.5 hover:border-[#afd0c0]"><div className="flex items-center gap-4"><Avatar name={p.name} large /><div><h2 className="text-lg font-semibold">{p.name}</h2><p className="text-sm text-[#77847c]">{p.phone}</p></div></div><p className="mt-5 text-sm text-[#607068]">{p.notes || "Sem observações"}</p><div className="mt-5 flex justify-between border-t pt-4 text-sm"><span>{pkg?.name || "Sem pacote"}</span><strong className="text-[#08684e]">{pkg ? `${remaining(pkg)} em haver` : "Cadastrar"}</strong></div></button>; })}</div>}
        {view === "record" && selected && <PatientRecord patient={selected} data={data} tab={recordTab} setTab={setRecordTab} used={used} remaining={remaining} setModal={setModal} onEdit={() => edit(selected)} onDeletePatient={() => setDeleteTarget({ action: "patient.delete", id: selected.id, label: selected.name })} onDelete={(action, id, label) => setDeleteTarget({ action, id, label })} />}
        {view === "packages" && <div className="grid gap-4 lg:grid-cols-2">{data.packages.map((pkg) => <PackageCard key={pkg.id} pkg={pkg} patient={name(pkg.patientId)} used={used(pkg.id)} remaining={remaining(pkg)} setModal={setModal} onDelete={() => setDeleteTarget({ action: "package.delete", id: pkg.id, label: pkg.name })} />)}</div>}
        {view === "sessions" && <SessionsDirectory data={data} onCreate={() => setModal("session")} onOpenPatient={openRecord} onDelete={(session) => setDeleteTarget({ action: "session.delete", id: session.id, label: `sessão de ${name(session.patientId)}` })} />}
        {view === "payments" && <FinanceDashboard data={data} name={name} onPayment={() => setModal("payment")} onExpense={() => setModal("expense")} onDeletePayment={(id, label) => setDeleteTarget({ action: "payment.delete", id, label })} onDeleteExpense={(id, label) => setDeleteTarget({ action: "expense.delete", id, label })} />}
        {view === "agenda" && <Agenda appointments={data.appointments} patients={data.patients} name={name} onCreate={() => setModal("appointment")} onStatus={(id, status) => mutate("appointment.status", { id, status }, "Agenda atualizada.")} onDelete={(a) => setDeleteTarget({ action: "appointment.delete", id: a.id, label: `agendamento de ${name(a.patientId)}` })} />}
      </div></main><ActionModal modal={modal} setModal={setModal} data={data} remaining={remaining} submit={submit} saving={saving} editingPatient={editingPatient} preferredPatientId={view === "record" ? selectedId : undefined} />
      <DeleteDialog target={deleteTarget} saving={saving} onClose={() => setDeleteTarget(null)} onConfirm={() => deleteTarget && mutate(deleteTarget.action, { id: deleteTarget.id }, "Registro removido com sucesso.")} />
  </div>;
}

function Stat({ icon: Icon, label, value, warning }: { icon: typeof Users; label: string; value: number; warning?: boolean }) { return <div className="rounded-2xl border bg-white p-5 shadow-sm"><div className="flex justify-between"><div><p className="text-sm text-[#66766d]">{label}</p><p className="mt-2 text-3xl font-semibold">{value}</p></div><span className={`grid size-12 place-items-center rounded-2xl ${warning ? "bg-[#fff2dc] text-[#96651f]" : "bg-[#e4f3eb] text-[#087052]"}`}><Icon className="size-5" /></span></div><p className="mt-3 text-xs text-[#8a958f]">Atualizado agora</p></div>; }
function FinanceDashboard({ data, name, onPayment, onExpense, onDeletePayment, onDeleteExpense }: { data: ClinicData; name: (id: number) => string; onPayment: () => void; onExpense: () => void; onDeletePayment: (id: number, label: string) => void; onDeleteExpense: (id: number, label: string) => void }) {
  const income = data.payments.reduce((sum, item) => sum + item.amountCents, 0); const expenses = data.expenses.reduce((sum, item) => sum + item.amountCents, 0); const balance = income - expenses; const receivable = data.packages.reduce((sum, item) => sum + Math.max(0, item.totalAmountCents - item.paidAmountCents), 0);
  const months = Array.from({ length: 6 }, (_, index) => { const date = new Date(); date.setMonth(date.getMonth() - (5 - index)); const key = date.toISOString().slice(0, 7); const label = new Intl.DateTimeFormat("pt-BR", { month: "short" }).format(date).replace(".", ""); const received = data.payments.filter((item) => item.paidAt.startsWith(key)).reduce((sum, item) => sum + item.amountCents, 0); const spent = data.expenses.filter((item) => item.paidAt.startsWith(key)).reduce((sum, item) => sum + item.amountCents, 0); return { key, label, received, spent }; });
  const max = Math.max(1, ...months.flatMap((item) => [item.received, item.spent]));
  const methods = ["Pix", "Cartão", "Dinheiro", "Transferência"].map((method) => ({ method, total: data.payments.filter((item) => item.method === method).reduce((sum, item) => sum + item.amountCents, 0) })).filter((item) => item.total > 0);
  return <div className="grid gap-6"><div className="flex flex-wrap justify-end gap-2"><Button variant="outline" onClick={onExpense}><TrendingDown /> Nova despesa</Button><Button className="bg-[#08684e]" onClick={onPayment}><TrendingUp /> Nova entrada</Button></div><section className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><FinanceMetric icon={TrendingUp} label="Total recebido" value={money(income)} tone="green" /><FinanceMetric icon={TrendingDown} label="Despesas" value={money(expenses)} tone="red" /><FinanceMetric icon={WalletCards} label="Saldo atual" value={money(balance)} tone={balance >= 0 ? "green" : "red"} /><FinanceMetric icon={ReceiptText} label="A receber" value={money(receivable)} tone="gold" /></section><section className="grid gap-6 xl:grid-cols-[1.5fr_.7fr]"><div className="premium-card rounded-[24px] border bg-white p-6"><div className="flex items-center justify-between"><div><h2 className="text-xl font-semibold">Fluxo dos últimos meses</h2><p className="text-sm text-[#7b8881]">Entradas e despesas registradas</p></div><span className="grid size-11 place-items-center rounded-xl bg-[#e8f3ed] text-[#087052]"><BarChart3 /></span></div><div className="mt-8 flex h-56 items-end gap-3 sm:gap-6">{months.map((month) => <div key={month.key} className="flex h-full flex-1 flex-col justify-end"><div className="flex flex-1 items-end justify-center gap-1"><div title={`Entradas: ${money(month.received)}`} className="min-h-1 w-3 rounded-t-md bg-[#0b7558] sm:w-5" style={{ height: `${Math.max(3, month.received / max * 100)}%` }} /><div title={`Despesas: ${money(month.spent)}`} className="min-h-1 w-3 rounded-t-md bg-[#df9f74] sm:w-5" style={{ height: `${Math.max(3, month.spent / max * 100)}%` }} /></div><p className="mt-3 text-center text-xs font-medium capitalize text-[#77847c]">{month.label}</p></div>)}</div><div className="mt-5 flex justify-center gap-5 text-xs text-[#718078]"><span className="flex items-center gap-2"><i className="size-2.5 rounded-full bg-[#0b7558]" /> Entradas</span><span className="flex items-center gap-2"><i className="size-2.5 rounded-full bg-[#df9f74]" /> Despesas</span></div></div><div className="premium-card rounded-[24px] border bg-white p-6"><h2 className="text-xl font-semibold">Recebimentos</h2><p className="text-sm text-[#7b8881]">Por forma de pagamento</p><div className="mt-6 grid gap-4">{methods.length ? methods.map((item) => <div key={item.method}><div className="mb-2 flex justify-between text-sm"><span>{item.method}</span><strong>{money(item.total)}</strong></div><div className="h-2 overflow-hidden rounded-full bg-[#edf1ee]"><div className="h-full rounded-full bg-gradient-to-r from-[#0b7558] to-[#5fa98e]" style={{ width: `${item.total / income * 100}%` }} /></div></div>) : <EmptyState text="Sem recebimentos ainda." />}</div></div></section><section className="grid gap-6 xl:grid-cols-2"><History title="Entradas" button="Registrar entrada" onCreate={onPayment} onDelete={onDeletePayment} rows={data.payments.map((item) => ({ id: item.id, title: name(item.patientId), subtitle: `${item.method} · ${dateBR(item.paidAt)}`, value: money(item.amountCents), icon: TrendingUp }))} /><History title="Despesas" button="Nova despesa" onCreate={onExpense} onDelete={onDeleteExpense} rows={data.expenses.map((item) => ({ id: item.id, title: item.description, subtitle: `${item.category} · ${dateBR(item.paidAt)}`, value: `- ${money(item.amountCents)}`, icon: TrendingDown }))} /></section></div>;
}
function FinanceMetric({ icon: Icon, label, value, tone }: { icon: typeof TrendingUp; label: string; value: string; tone: "green" | "red" | "gold" }) { const styles = tone === "red" ? "bg-[#fff0eb] text-[#b65f43]" : tone === "gold" ? "bg-[#fff6df] text-[#9a6e1e]" : "bg-[#e5f3eb] text-[#087052]"; return <div className="premium-card rounded-[22px] border bg-white p-5"><div className="flex items-start justify-between"><div><p className="text-sm text-[#6e7d75]">{label}</p><p className="mt-3 text-2xl font-semibold tracking-tight">{value}</p></div><span className={`grid size-11 place-items-center rounded-xl ${styles}`}><Icon className="size-5" /></span></div></div>; }
function PatientTable({ patients, packages, used, remaining, selectedId, onSelect }: { patients: Patient[]; packages: ClinicPackage[]; used: (id: number) => number; remaining: (p: ClinicPackage) => number; selectedId: number; onSelect: (id: number) => void }) { return <div className="overflow-hidden rounded-2xl border bg-white shadow-sm"><div className="border-b px-6 py-5"><h2 className="text-xl font-semibold">Pacientes recentes</h2><p className="text-sm text-[#7b8881]">Pacotes, sessões e pagamentos em uma visão.</p></div><div className="overflow-x-auto"><table className="w-full min-w-[680px] text-left text-sm"><thead className="bg-[#fafbfa] text-xs uppercase text-[#7e8a83]"><tr><th className="px-6 py-3">Paciente</th><th className="px-4">Pacote</th><th className="px-4 text-center">Realizadas</th><th className="px-4 text-center">Restantes</th><th className="px-4">Pagamento</th><th /></tr></thead><tbody className="divide-y">{patients.map((p) => { const pkg = packages.find((item) => item.patientId === p.id); return <tr key={p.id} onClick={() => onSelect(p.id)} className={`cursor-pointer hover:bg-[#f5faf7] ${selectedId === p.id ? "bg-[#f0f8f4]" : ""}`}><td className="px-6 py-4"><div className="flex items-center gap-3"><Avatar name={p.name} /><div><strong>{p.name}</strong><p className="text-xs text-[#859087]">{p.phone}</p></div></div></td><td className="px-4">{pkg?.name || "Sem pacote"}</td><td className="px-4 text-center">{pkg ? used(pkg.id) : 0}</td><td className="px-4 text-center"><span className="rounded-full bg-[#e3f3ea] px-3 py-1 font-semibold text-[#08684e]">{pkg ? remaining(pkg) : 0}</span></td><td className="px-4">{pkg && <Status value={pkg.paymentStatus} />}</td><td><ChevronRight className="size-4" /></td></tr>; })}</tbody></table></div></div>; }
function PatientCard({ patient, pkg, used, remaining, onOpen, onEdit, onDelete }: { patient?: Patient; pkg?: ClinicPackage; used: (id: number) => number; remaining: (p: ClinicPackage) => number; onOpen: (p: Patient) => void; onEdit: (p: Patient) => void; onDelete: (p: Patient) => void }) { if (!patient) return null; return <div className="premium-card rounded-[24px] border bg-white p-6 shadow-sm"><div className="flex items-start gap-4"><Avatar name={patient.name} large /><div className="min-w-0 flex-1"><h2 className="text-xl font-semibold">{patient.name}</h2><p className="text-sm text-[#738078]">{patient.phone || "Sem telefone"}</p><p className="mt-1 truncate text-xs text-[#87928c]">{patient.notes || "Sem observações"}</p></div><div className="flex"><Button variant="ghost" size="icon" onClick={() => onEdit(patient)} title="Editar paciente"><Pencil className="size-4" /></Button><Button variant="ghost" size="icon" className="text-red-500 hover:text-red-600" onClick={() => onDelete(patient)} title="Remover paciente"><Trash2 className="size-4" /></Button></div></div><div className="my-6 border-t" />{pkg ? <><div className="flex justify-between"><div><p className="text-xs uppercase tracking-wider text-[#849087]">Pacote atual</p><strong>{pkg.name}</strong></div><Status value={pkg.status} /></div><div className="mt-6 flex justify-between text-sm"><strong>{used(pkg.id)} de {pkg.totalSessions} realizadas</strong><span>{remaining(pkg)} restantes</span></div><Progress value={used(pkg.id) / pkg.totalSessions * 100} className="mt-3 h-3" /><div className="mt-6 rounded-2xl bg-gradient-to-br from-[#eef8f2] to-[#f8fbf9] p-4"><div className="flex justify-between"><span>Pagamento</span><Status value={pkg.paymentStatus} /></div><strong className="mt-2 block">{money(pkg.paidAmountCents)} de {money(pkg.totalAmountCents)}</strong><p className="text-xs text-[#819087]">Último: {dateBR(pkg.lastPaymentAt)} · {pkg.paymentMethod}</p></div></> : <p className="rounded-xl bg-[#f7f9f7] p-4 text-sm text-[#718078]">Paciente sem pacote ativo.</p>}<Button className="mt-6 w-full bg-[#08684e] shadow-sm" onClick={() => onOpen(patient)}><FileText /> Abrir prontuário completo</Button></div>; }

function PatientRecord({ patient, data, tab, setTab, used, remaining, setModal, onEdit, onDeletePatient, onDelete }: { patient: Patient; data: ClinicData; tab: RecordTab; setTab: (tab: RecordTab) => void; used: (id: number) => number; remaining: (pkg: ClinicPackage) => number; setModal: (modal: Modal) => void; onEdit: () => void; onDeletePatient: () => void; onDelete: (action: string, id: number, label: string) => void }) {
  const [month, setMonth] = useState("");
  const patientPackages = data.packages.filter((item) => item.patientId === patient.id);
  const patientSessions = data.sessions.filter((item) => item.patientId === patient.id && (!month || item.performedAt.startsWith(month)));
  const patientPayments = data.payments.filter((item) => item.patientId === patient.id);
  const appointments = data.appointments.filter((item) => item.patientId === patient.id);
  const totalRemaining = patientPackages.reduce((sum, item) => sum + remaining(item), 0);
  const totalPaid = patientPayments.reduce((sum, item) => sum + item.amountCents, 0);
  const totalPending = patientPackages.reduce((sum, item) => sum + Math.max(0, item.totalAmountCents - item.paidAmountCents), 0);
  const tabs: [RecordTab, string][] = [["summary", "Resumo"], ["sessions", "Sessões"], ["packages", "Pacotes"], ["payments", "Pagamentos"], ["notes", "Observações"]];
  return <div className="grid gap-6">
    <section className="overflow-hidden rounded-[28px] bg-gradient-to-br from-[#064c3a] to-[#0a7256] text-white shadow-xl shadow-emerald-950/10"><div className="p-6 sm:p-8"><div className="flex flex-wrap items-start gap-5"><span className="grid size-20 place-items-center rounded-[24px] bg-white/15 text-2xl font-semibold ring-1 ring-white/20">{initials(patient.name)}</span><div className="min-w-[220px] flex-1"><div className="flex flex-wrap items-center gap-3"><h2 className="font-serif text-3xl font-semibold">{patient.name}</h2><span className="rounded-full bg-emerald-300/15 px-3 py-1 text-xs font-medium text-emerald-100">Prontuário ativo</span></div><p className="mt-2 text-white/65">{patient.phone || "Sem telefone"} {patient.email ? `· ${patient.email}` : ""}</p><p className="mt-3 max-w-2xl text-sm text-white/55">{patient.notes || "Nenhuma observação geral cadastrada."}</p></div><div className="flex gap-2"><Button className="border-white/20 bg-white/10 text-white hover:bg-white/20" onClick={onEdit}><Pencil /> Editar</Button><Button size="icon" className="border-white/20 bg-white/10 text-white hover:bg-red-500/70" onClick={onDeletePatient}><Trash2 /></Button></div></div><div className="mt-7 grid gap-3 sm:grid-cols-4"><RecordMetric label="Sessões realizadas" value={String(data.sessions.filter((item) => item.patientId === patient.id).length)} /><RecordMetric label="Sessões disponíveis" value={String(totalRemaining)} /><RecordMetric label="Total pago" value={money(totalPaid)} /><RecordMetric label="Valor pendente" value={money(totalPending)} /></div></div><div className="flex overflow-x-auto border-t border-white/10 bg-black/5 px-3 sm:px-6">{tabs.map(([key, label]) => <button key={key} onClick={() => setTab(key)} className={`whitespace-nowrap border-b-2 px-4 py-4 text-sm font-medium transition ${tab === key ? "border-[#ead59c] text-white" : "border-transparent text-white/55 hover:text-white"}`}>{label}</button>)}</div></section>

    {tab === "summary" && <div className="grid gap-6 xl:grid-cols-[1.35fr_.65fr]"><div className="grid gap-4"><SectionTitle title="Pacotes e sessões" subtitle="Situação atual do tratamento" action={<Button size="sm" onClick={() => setModal("package")} className="bg-[#08684e]"><Plus /> Novo pacote</Button>} />{patientPackages.length ? patientPackages.map((pkg) => <RecordPackage key={pkg.id} pkg={pkg} used={used(pkg.id)} remaining={remaining(pkg)} />) : <div className="premium-card rounded-[22px] border bg-white"><EmptyState text="Nenhum pacote cadastrado." /></div>}</div><div className="grid content-start gap-4"><div className="premium-card rounded-[22px] border bg-white p-5"><SectionTitle title="Ações rápidas" subtitle="Registre sem sair do prontuário" /><div className="mt-5 grid gap-2"><Button className="bg-[#08684e]" onClick={() => setModal("session")}><Stethoscope /> Registrar sessão</Button><Button variant="outline" onClick={() => setModal("payment")}><Banknote /> Registrar pagamento</Button><Button variant="outline" onClick={() => setModal("appointment")}><CalendarDays /> Agendar atendimento</Button></div></div><div className="premium-card rounded-[22px] border bg-white p-5"><SectionTitle title="Próximos atendimentos" subtitle={`${appointments.length} registro(s)`} /><div className="mt-4 grid gap-3">{appointments.slice(0, 4).map((item) => <div key={item.id} className="flex items-center justify-between rounded-xl bg-[#f5f9f6] p-3 text-sm"><div><strong>{dateBR(item.scheduledAt)}</strong><p className="text-[#748179]">{item.scheduledAt.slice(11, 16)} · {item.durationMinutes} min</p></div><Status value={item.status} /></div>)}{!appointments.length && <p className="text-sm text-[#7d8a83]">Nenhum agendamento.</p>}</div></div></div></div>}

    {tab === "sessions" && <div className="grid gap-5"><div className="flex flex-wrap items-end justify-between gap-3"><SectionTitle title="Histórico de sessões" subtitle="Todas as evoluções deste paciente" /><div className="flex gap-2"><label className="grid gap-1 text-xs text-[#748179]">Filtrar por mês<Input type="month" value={month} onChange={(event) => setMonth(event.target.value)} className="h-10 bg-white" /></label><Button className="mt-auto bg-[#08684e]" onClick={() => setModal("session")}><Plus /> Nova sessão</Button></div></div>{patientSessions.length ? <div className="grid gap-4">{patientSessions.map((session, index) => <SessionRecord key={session.id} session={session} number={data.sessions.filter((item) => item.patientId === patient.id).length - index} packageName={data.packages.find((item) => item.id === session.packageId)?.name || "Pacote"} onDelete={() => onDelete("session.delete", session.id, `sessão de ${dateBR(session.performedAt)}`)} />)}</div> : <div className="premium-card rounded-[22px] border bg-white"><EmptyState text="Nenhuma sessão encontrada neste período." /></div>}</div>}

    {tab === "packages" && <div className="grid gap-4 lg:grid-cols-2">{patientPackages.map((pkg) => <PackageCard key={pkg.id} pkg={pkg} patient={patient.name} used={used(pkg.id)} remaining={remaining(pkg)} setModal={setModal} onDelete={() => onDelete("package.delete", pkg.id, pkg.name)} />)}{!patientPackages.length && <div className="premium-card rounded-[22px] border bg-white lg:col-span-2"><EmptyState text="Nenhum pacote cadastrado." /></div>}</div>}

    {tab === "payments" && <div className="grid gap-6"><section className="grid gap-4 sm:grid-cols-3"><FinanceMetric icon={TrendingUp} label="Total pago" value={money(totalPaid)} tone="green" /><FinanceMetric icon={ReceiptText} label="A pagar" value={money(totalPending)} tone="gold" /><FinanceMetric icon={WalletCards} label="Último pagamento" value={dateBR(patientPayments[0]?.paidAt)} tone="green" /></section><History title="Pagamentos do paciente" button="Registrar pagamento" onCreate={() => setModal("payment")} onDelete={(id, label) => onDelete("payment.delete", id, label)} rows={patientPayments.map((item) => ({ id: item.id, title: data.packages.find((pkg) => pkg.id === item.packageId)?.name || patient.name, subtitle: `${item.method} · ${dateBR(item.paidAt)}`, value: money(item.amountCents), icon: TrendingUp }))} /></div>}

    {tab === "notes" && <div className="premium-card rounded-[24px] border bg-white p-6"><div className="flex items-start justify-between gap-4"><SectionTitle title="Observações gerais" subtitle="Informações permanentes do prontuário" /><Button variant="outline" onClick={onEdit}><Pencil /> Editar</Button></div><div className="mt-6 min-h-40 whitespace-pre-wrap rounded-2xl bg-[#f7faf8] p-5 leading-relaxed text-[#52645b]">{patient.notes || "Nenhuma observação geral cadastrada para este paciente."}</div></div>}
  </div>;
}

function RecordMetric({ label, value }: { label: string; value: string }) { return <div className="rounded-2xl border border-white/10 bg-white/10 p-4 backdrop-blur"><p className="text-xs text-white/55">{label}</p><strong className="mt-1 block text-xl">{value}</strong></div>; }
function SectionTitle({ title, subtitle, action }: { title: string; subtitle: string; action?: React.ReactNode }) { return <div className="flex items-center justify-between gap-3"><div><h3 className="text-xl font-semibold">{title}</h3><p className="text-sm text-[#7b8881]">{subtitle}</p></div>{action}</div>; }
function RecordPackage({ pkg, used, remaining }: { pkg: ClinicPackage; used: number; remaining: number }) { const paidSessions = pkg.totalAmountCents > 0 ? Math.min(pkg.totalSessions, Math.floor(pkg.paidAmountCents / pkg.totalAmountCents * pkg.totalSessions)) : 0; return <div className="premium-card rounded-[22px] border bg-white p-5"><div className="flex flex-wrap items-start justify-between gap-3"><div><div className="flex items-center gap-2"><h3 className="font-semibold">{pkg.name}</h3><Status value={pkg.status} /></div><p className="mt-1 text-sm text-[#7b8881]">Contratado em {dateBR(pkg.purchasedAt)}</p></div><Status value={pkg.paymentStatus} /></div><div className="mt-5 flex justify-between text-sm"><strong>{used} realizadas</strong><span>{remaining} disponíveis</span></div><Progress value={used / pkg.totalSessions * 100} className="mt-2 h-3" /><div className="mt-5 grid gap-3 rounded-2xl bg-[#f6f9f7] p-4 text-sm sm:grid-cols-4"><div><span className="text-[#7b8881]">Pacote</span><strong className="block">{pkg.totalSessions} sessões</strong></div><div><span className="text-[#7b8881]">Cobertas pelo pagamento</span><strong className="block">{paidSessions} sessões</strong></div><div><span className="text-[#7b8881]">Pago</span><strong className="block">{money(pkg.paidAmountCents)}</strong></div><div><span className="text-[#7b8881]">Pendente</span><strong className="block">{money(Math.max(0, pkg.totalAmountCents - pkg.paidAmountCents))}</strong></div></div><p className="mt-3 text-xs text-[#829087]">Último pagamento: {dateBR(pkg.lastPaymentAt)} · {pkg.paymentMethod}</p></div>; }
function SessionRecord({ session, number, packageName, patient, onOpenPatient, onDelete }: { session: Session; number?: number; packageName: string; patient?: Patient; onOpenPatient?: () => void; onDelete: () => void }) {
  const [open, setOpen] = useState(false);
  const hasDetails = Boolean(session.measurementIn || session.measurementOut || session.notes || session.occurrences);
  return <article className="premium-card overflow-hidden rounded-[20px] border bg-white shadow-sm transition hover:border-[#c4dacf]">
    <div className="flex items-center gap-3 p-4 sm:gap-4 sm:p-5">
      {patient ? <Avatar name={patient.name} /> : <span className="grid size-11 shrink-0 place-items-center rounded-xl bg-[#e5f3eb] font-semibold text-[#087052]">{number}ª</span>}
      <button type="button" className="min-w-0 flex-1 text-left" onClick={() => setOpen((value) => !value)}>
        <div className="flex flex-wrap items-center gap-2"><h3 className="font-semibold">{patient?.name || session.procedureType || "Sessão registrada"}</h3>{session.occurrences && <span className="rounded-full bg-amber-100 px-2.5 py-1 text-[11px] font-medium text-amber-800">Com intercorrência</span>}{(session.measurementIn || session.measurementOut) && <span className="rounded-full bg-[#eaf5ef] px-2.5 py-1 text-[11px] font-medium text-[#087052]">Com medidas</span>}</div>
        <p className="mt-1 truncate text-sm text-[#75837b]">{patient && `${session.procedureType || "Sessão registrada"} · `}{dateBR(session.performedAt)} · {packageName}</p>
      </button>
      {patient && onOpenPatient && <Button variant="ghost" size="sm" className="hidden text-[#087052] sm:inline-flex" onClick={onOpenPatient}>Prontuário</Button>}
      <button type="button" onClick={() => setOpen((value) => !value)} aria-label={open ? "Fechar detalhes" : "Ver detalhes"} className="grid size-9 shrink-0 place-items-center rounded-full text-[#607168] transition hover:bg-[#eef5f1]"><ChevronDown className={`size-5 transition-transform ${open ? "rotate-180" : ""}`} /></button>
    </div>
    {open && <div className="border-t bg-[#fbfcfb] px-4 py-5 sm:px-5">
      {!hasDetails && <p className="rounded-xl bg-white p-4 text-sm text-[#75837b]">Esta sessão não possui observações adicionais.</p>}
      {(session.measurementIn || session.measurementOut) && <div className="grid gap-3 sm:grid-cols-2"><div className="rounded-xl bg-white p-4"><p className="text-xs uppercase tracking-wide text-[#849087]">Medida de entrada</p><strong className="mt-1 block">{session.measurementIn || "Não informada"}</strong></div><div className="rounded-xl bg-[#eef7f2] p-4"><p className="text-xs uppercase tracking-wide text-[#849087]">Medida de saída</p><strong className="mt-1 block">{session.measurementOut || "Não informada"}</strong></div></div>}
      {session.notes && <div className="mt-4"><p className="text-xs font-semibold uppercase tracking-wide text-[#849087]">Evolução e observações</p><p className="mt-1 whitespace-pre-wrap text-sm leading-relaxed text-[#53645b]">{session.notes}</p></div>}
      {session.occurrences && <div className="mt-4 rounded-xl border border-amber-200 bg-amber-50 p-4"><p className="text-xs font-semibold uppercase tracking-wide text-amber-800">Intercorrências</p><p className="mt-1 whitespace-pre-wrap text-sm text-amber-900">{session.occurrences}</p></div>}
      <div className="mt-5 flex justify-end"><Button variant="ghost" size="sm" className="text-red-500 hover:text-red-600" onClick={onDelete}><Trash2 className="size-4" /> Remover sessão</Button></div>
    </div>}
  </article>;
}
function PackageCard({ pkg, patient, used, remaining, setModal, onDelete }: { pkg: ClinicPackage; patient: string; used: number; remaining: number; setModal: (m: Modal) => void; onDelete: () => void }) { return <div className="premium-card rounded-[24px] border bg-white p-6 shadow-sm"><div className="flex justify-between gap-3"><div><p className="text-sm text-[#728078]">{patient}</p><h2 className="text-xl font-semibold">{pkg.name}</h2></div><div className="flex items-start gap-1"><Status value={pkg.paymentStatus} /><Button variant="ghost" size="icon" className="text-red-500" onClick={onDelete} title="Remover pacote"><Trash2 className="size-4" /></Button></div></div><div className="mt-6 flex items-end justify-between"><div><p className="text-3xl font-semibold text-[#08684e]">{remaining}</p><p className="text-sm text-[#748179]">sessões em haver</p></div><p className="text-sm"><strong>{used}</strong> de {pkg.totalSessions}</p></div><Progress value={used / pkg.totalSessions * 100} className="mt-4 h-3" /><div className="mt-5 grid grid-cols-2 gap-3 rounded-2xl bg-[#f7f9f7] p-4 text-sm"><div>Valor<br /><strong>{money(pkg.totalAmountCents)}</strong></div><div>Pago<br /><strong>{money(pkg.paidAmountCents)}</strong></div><div>Contratado<br /><strong>{dateBR(pkg.purchasedAt)}</strong></div><div>Forma<br /><strong>{pkg.paymentMethod}</strong></div></div><div className="mt-5 flex gap-2"><Button className="flex-1 bg-[#08684e]" onClick={() => setModal("session")}>Sessão</Button><Button variant="outline" className="flex-1" onClick={() => setModal("payment")}>Pagamento</Button></div></div>; }
function SessionsDirectory({ data, onCreate, onOpenPatient, onDelete }: { data: ClinicData; onCreate: () => void; onOpenPatient: (id: number) => void; onDelete: (session: Session) => void }) {
  const [patientId, setPatientId] = useState("");
  const [month, setMonth] = useState("");
  const [procedure, setProcedure] = useState("");
  const currentMonth = today.slice(0, 7);
  const procedures = Array.from(new Set(data.sessions.map((session) => session.procedureType).filter(Boolean))).sort();
  const sessions = data.sessions.filter((session) => (!patientId || session.patientId === Number(patientId)) && (!month || session.performedAt.startsWith(month)) && (!procedure || session.procedureType === procedure));
  const uniquePatients = new Set(data.sessions.filter((session) => session.performedAt.startsWith(currentMonth)).map((session) => session.patientId)).size;
  const filtersActive = Boolean(patientId || month || procedure);
  return <div className="grid gap-5">
    <section className="grid gap-3 sm:grid-cols-3">
      <Stat icon={CalendarDays} label="Sessões hoje" value={data.sessions.filter((session) => session.performedAt.slice(0, 10) === today).length} />
      <Stat icon={FileText} label="Sessões neste mês" value={data.sessions.filter((session) => session.performedAt.startsWith(currentMonth)).length} />
      <Stat icon={Users} label="Pacientes atendidos" value={uniquePatients} />
    </section>
    <div className="premium-card rounded-[22px] border bg-white p-5">
      <div className="flex flex-wrap items-end gap-3">
        <div className="min-w-[220px] flex-1"><Label>Paciente</Label><NativeSelect value={patientId} onChange={(event) => setPatientId(event.target.value)} className="mt-2 h-11 w-full"><NativeSelectOption value="">Todos os pacientes</NativeSelectOption>{data.patients.map((patient) => <NativeSelectOption key={patient.id} value={patient.id}>{patient.name}</NativeSelectOption>)}</NativeSelect></div>
        <div className="min-w-[190px]"><Label>Procedimento</Label><NativeSelect value={procedure} onChange={(event) => setProcedure(event.target.value)} className="mt-2 h-11 w-full"><NativeSelectOption value="">Todos os procedimentos</NativeSelectOption>{procedures.map((item) => <NativeSelectOption key={item} value={item}>{item}</NativeSelectOption>)}</NativeSelect></div>
        <div><Label>Mês</Label><Input type="month" value={month} onChange={(event) => setMonth(event.target.value)} className="mt-2 h-11 bg-white" /></div>
        {filtersActive && <Button variant="ghost" onClick={() => { setPatientId(""); setMonth(""); setProcedure(""); }}>Limpar filtros</Button>}
        <Button className="bg-[#08684e]" onClick={onCreate}><Plus /> Registrar sessão</Button>
      </div>
      <div className="mt-4 flex items-center justify-between border-t pt-4 text-sm text-[#718078]"><span>{sessions.length} {sessions.length === 1 ? "sessão encontrada" : "sessões encontradas"}</span><span>Clique em uma sessão para ver a evolução</span></div>
    </div>
    <div className="grid gap-3">{sessions.length ? sessions.map((session) => { const patient = data.patients.find((item) => item.id === session.patientId); return <SessionRecord key={session.id} session={session} patient={patient} packageName={data.packages.find((pkg) => pkg.id === session.packageId)?.name || "Pacote"} onOpenPatient={() => onOpenPatient(session.patientId)} onDelete={() => onDelete(session)} />; }) : <div className="premium-card rounded-[22px] border bg-white"><EmptyState text="Nenhuma sessão encontrada com esses filtros." /></div>}</div>
  </div>;
}
function History({ title, button, onCreate, onDelete, rows }: { title: string; button: string; onCreate: () => void; onDelete: (id: number, label: string) => void; rows: { id: number; title: string; subtitle: string; value: string; icon: typeof Stethoscope }[] }) { return <div className="premium-card overflow-hidden rounded-[24px] border bg-white"><div className="flex items-center justify-between border-b p-6"><h2 className="text-xl font-semibold">{title}</h2><Button onClick={onCreate} className="bg-[#08684e]"><Plus />{button}</Button></div><div className="divide-y">{rows.length ? rows.map((row) => <div key={row.id} className="group flex items-center gap-4 px-6 py-4 hover:bg-[#f8fbf9]"><span className="grid size-11 place-items-center rounded-xl bg-[#e5f3eb] text-[#087052]"><row.icon className="size-5" /></span><div className="flex-1"><strong>{row.title}</strong><p className="text-sm text-[#78857d]">{row.subtitle}</p></div><strong className="text-[#08684e]">{row.value}</strong><Button variant="ghost" size="icon" className="text-red-500 opacity-60 transition group-hover:opacity-100" onClick={() => onDelete(row.id, `${title.toLowerCase()} de ${row.title}`)}><Trash2 className="size-4" /></Button></div>) : <EmptyState text="Nenhum registro ainda." />}</div></div>; }
function Agenda({ appointments, patients, name, onCreate, onStatus, onDelete }: { appointments: Appointment[]; patients: Patient[]; name: (id: number) => string; onCreate: () => void; onStatus: (id: number, status: string) => void; onDelete: (appointment: Appointment) => void }) {
  return <div className="grid gap-6 xl:grid-cols-[280px_1fr]"><div className="rounded-[26px] bg-gradient-to-br from-[#07533f] to-[#0b7558] p-6 text-white shadow-lg shadow-emerald-950/10"><CalendarDays className="text-[#e4cf94]" /><p className="mt-8 text-white/65">Hoje</p><p className="font-serif text-5xl">{new Date().getDate()}</p><p className="capitalize">{new Intl.DateTimeFormat("pt-BR", { weekday: "long", month: "long" }).format(new Date())}</p><Button onClick={onCreate} className="mt-8 w-full bg-white text-[#07533f] hover:bg-[#f4fbf7]"><Plus /> Agendar</Button></div><div className="premium-card rounded-[24px] border bg-white p-6"><div><h2 className="text-xl font-semibold">Próximos atendimentos</h2><p className="text-sm text-[#7b8881]">Confirme pelo WhatsApp com uma mensagem pronta</p></div><div className="mt-5 divide-y">{appointments.length ? appointments.map((appointment) => { const patient = patients.find((item) => item.id === appointment.patientId); const digits = patient?.phone.replace(/\D/g, "") || ""; const phone = digits.length === 10 || digits.length === 11 ? `55${digits}` : digits; const when = `${dateBR(appointment.scheduledAt)} às ${appointment.scheduledAt.slice(11, 16)}`; const message = encodeURIComponent(`Olá, ${patient?.name || ""}! Tudo bem? Aqui é da Clínica Essência, da Dra. Maria Carolini. Gostaria de confirmar seu atendimento no dia ${when}. Podemos confirmar?`); return <div key={appointment.id} className="flex flex-wrap items-center gap-4 py-4"><div className="w-16 text-center"><strong className="text-lg text-[#08684e]">{appointment.scheduledAt.slice(11, 16)}</strong><p className="text-xs">{dateBR(appointment.scheduledAt)}</p></div><Avatar name={name(appointment.patientId)} /><div className="min-w-[150px] flex-1"><strong>{name(appointment.patientId)}</strong><p className="text-sm text-[#77847c]">{appointment.durationMinutes} minutos</p></div><Status value={appointment.status} />{phone && <a href={`https://wa.me/${phone}?text=${message}`} target="_blank" rel="noreferrer" className="inline-flex h-9 items-center gap-2 rounded-lg bg-[#25d366] px-3 text-sm font-medium text-white transition hover:bg-[#1fb759]"><MessageCircle className="size-4" /> WhatsApp</a>}{appointment.status === "Agendado" && <Button variant="outline" size="sm" onClick={() => onStatus(appointment.id, "Concluído")}><CheckCircle2 className="size-4" /> Concluir</Button>}<Button variant="ghost" size="icon" className="text-red-500" onClick={() => onDelete(appointment)}><Trash2 className="size-4" /></Button></div>; }) : <EmptyState text="Nenhum atendimento agendado." />}</div></div></div>;
}

function ActionModal({ modal, setModal, data, remaining, submit, saving, editingPatient, preferredPatientId }: { modal: Modal; setModal: (m: Modal) => void; data: ClinicData; remaining: (p: ClinicPackage) => number; submit: (e: FormEvent<HTMLFormElement>, action: string) => void; saving: boolean; editingPatient: Patient | null; preferredPatientId?: number }) {
  if (!modal) return null;
  const title = { patient: "Novo paciente", patientEdit: "Editar paciente", package: "Novo pacote", session: "Registrar sessão", payment: "Registrar entrada", appointment: "Novo agendamento", expense: "Nova despesa" }[modal];
  const action = { patient: "patient.create", patientEdit: "patient.update", package: "package.create", session: "session.create", payment: "payment.create", appointment: "appointment.create", expense: "expense.create" }[modal];
  return <Dialog open onOpenChange={(open) => !open && setModal(null)}><DialogContent className="max-h-[90vh] overflow-y-auto rounded-[24px] border-[#dce8e1] sm:max-w-[600px]"><DialogHeader><DialogTitle className="font-serif text-2xl">{title}</DialogTitle><DialogDescription>Preencha os dados abaixo e salve.</DialogDescription></DialogHeader><form onSubmit={(event) => submit(event, action)} className="grid gap-4">
    {modal === "patientEdit" && editingPatient && <><input type="hidden" name="id" value={editingPatient.id} /><Field label="Nome completo" name="name" required defaultValue={editingPatient.name} /><Field label="Telefone" name="phone" defaultValue={editingPatient.phone} /><Field label="E-mail" name="email" type="email" defaultValue={editingPatient.email} /><TextField label="Observações" name="notes" defaultValue={editingPatient.notes} /></>}
    {modal === "patient" && <><Field label="Nome completo" name="name" required /><Field label="Telefone" name="phone" /><Field label="E-mail" name="email" type="email" /><TextField label="Observações" name="notes" /></>}
    {modal === "package" && <><PatientSelect patients={data.patients} defaultValue={preferredPatientId} /><Field label="Quantidade de sessões" name="totalSessions" type="number" min="1" defaultValue="5" required /><Field label="Data da contratação" name="purchasedAt" type="date" defaultValue={today} required /><Field label="Nome do pacote" name="name" /><Field label="Valor total (R$)" name="totalAmount" type="number" step="0.01" min="0" required /><Field label="Valor pago (R$)" name="paidAmount" type="number" step="0.01" defaultValue="0" /><Method name="paymentMethod" /></>}
    {modal === "session" && <><PackageSelect packages={data.packages.filter((pkg) => remaining(pkg) > 0)} data={data} remaining={remaining} preferredPatientId={preferredPatientId} /><Field label="Data da sessão" name="performedAt" type="date" defaultValue={today} required /><Field label="Procedimento realizado" name="procedureType" placeholder="Ex.: Massagem modeladora, fisioterapia" /><div className="grid gap-4 sm:grid-cols-2"><Field label="Medida de entrada" name="measurementIn" placeholder="Ex.: 92 cm" /><Field label="Medida de saída" name="measurementOut" placeholder="Ex.: 89 cm" /></div><TextField label="Evolução e observações" name="notes" /><TextField label="Intercorrências durante a sessão" name="occurrences" /></>}
    {modal === "payment" && <><PackageSelect packages={data.packages.filter((pkg) => pkg.paymentStatus !== "Pago")} data={data} remaining={remaining} preferredPatientId={preferredPatientId} /><Field label="Valor recebido (R$)" name="amount" type="number" step="0.01" min="0.01" required /><Field label="Data" name="paidAt" type="date" defaultValue={today} required /><Method name="method" /><TextField label="Observações" name="notes" /></>}
    {modal === "expense" && <><Field label="Descrição" name="description" placeholder="Ex.: Aluguel, materiais, internet" required /><ExpenseCategory /><Field label="Valor (R$)" name="amount" type="number" step="0.01" min="0.01" required /><Field label="Data do pagamento" name="paidAt" type="date" defaultValue={today} required /><TextField label="Observações" name="notes" /></>}
    {modal === "appointment" && <><PatientSelect patients={data.patients} defaultValue={preferredPatientId} /><Field label="Data e horário" name="scheduledAt" type="datetime-local" required /><Field label="Duração em minutos" name="durationMinutes" type="number" defaultValue="50" /><TextField label="Observações" name="notes" /></>}
    <div className="flex justify-end gap-2"><Button type="button" variant="outline" onClick={() => setModal(null)}>Cancelar</Button><Button disabled={saving} className="bg-[#08684e]">{saving ? "Salvando..." : "Salvar"}</Button></div>
  </form></DialogContent></Dialog>;
}
function DeleteDialog({ target, saving, onClose, onConfirm }: { target: DeleteTarget; saving: boolean; onClose: () => void; onConfirm: () => void }) { return <Dialog open={Boolean(target)} onOpenChange={(open) => !open && onClose()}><DialogContent className="rounded-[24px] sm:max-w-[440px]"><DialogHeader><DialogTitle className="font-serif text-2xl">Remover registro?</DialogTitle><DialogDescription>Você está removendo <strong>{target?.label}</strong>. Esta ação não poderá ser desfeita.</DialogDescription></DialogHeader><div className="flex justify-end gap-2"><Button variant="outline" onClick={onClose}>Cancelar</Button><Button disabled={saving} className="bg-red-600 hover:bg-red-700" onClick={onConfirm}><Trash2 /> {saving ? "Removendo..." : "Remover"}</Button></div></DialogContent></Dialog>; }
function EmptyState({ text }: { text: string }) { return <div className="grid place-items-center gap-2 py-14 text-center text-[#7d8a83]"><span className="grid size-12 place-items-center rounded-full bg-[#edf5f0]"><Sparkles className="size-5 text-[#398069]" /></span><p>{text}</p></div>; }
function Field({ label, name, ...props }: { label: string; name: string } & React.ComponentProps<typeof Input>) { return <div className="grid gap-2"><Label htmlFor={name}>{label}</Label><Input id={name} name={name} className="h-11" {...props} /></div>; }
function TextField({ label, name, defaultValue }: { label: string; name: string; defaultValue?: string }) { return <div className="grid gap-2"><Label htmlFor={name}>{label}</Label><Textarea id={name} name={name} defaultValue={defaultValue} /></div>; }
function PatientSelect({ patients, defaultValue }: { patients: Patient[]; defaultValue?: number }) { return <div className="grid gap-2"><Label>Paciente</Label><NativeSelect name="patientId" required className="h-11 w-full" defaultValue={defaultValue || ""}><NativeSelectOption value="">Selecione</NativeSelectOption>{patients.map((patient) => <NativeSelectOption key={patient.id} value={patient.id}>{patient.name}</NativeSelectOption>)}</NativeSelect></div>; }
function PackageSelect({ packages, data, remaining, preferredPatientId }: { packages: ClinicPackage[]; data: ClinicData; remaining: (p: ClinicPackage) => number; preferredPatientId?: number }) { const visible = preferredPatientId ? packages.filter((pkg) => pkg.patientId === preferredPatientId) : packages; return <div className="grid gap-2"><Label>Pacote</Label><NativeSelect name="packageId" required className="h-11 w-full" defaultValue={visible[0]?.id || ""}><NativeSelectOption value="">Selecione</NativeSelectOption>{visible.map((pkg) => <NativeSelectOption key={pkg.id} value={pkg.id}>{data.patients.find((patient) => patient.id === pkg.patientId)?.name} · {pkg.name} · {remaining(pkg)} restantes</NativeSelectOption>)}</NativeSelect></div>; }
function Method({ name }: { name: string }) { return <div className="grid gap-2"><Label>Forma de pagamento</Label><NativeSelect name={name} className="h-11 w-full"><NativeSelectOption>Pix</NativeSelectOption><NativeSelectOption>Dinheiro</NativeSelectOption><NativeSelectOption>Cartão</NativeSelectOption><NativeSelectOption>Transferência</NativeSelectOption></NativeSelect></div>; }
function ExpenseCategory() { return <div className="grid gap-2"><Label>Categoria</Label><NativeSelect name="category" className="h-11 w-full"><NativeSelectOption>Materiais</NativeSelectOption><NativeSelectOption>Aluguel</NativeSelectOption><NativeSelectOption>Serviços</NativeSelectOption><NativeSelectOption>Equipamentos</NativeSelectOption><NativeSelectOption>Marketing</NativeSelectOption><NativeSelectOption>Impostos</NativeSelectOption><NativeSelectOption>Outros</NativeSelectOption></NativeSelect></div>; }
function Avatar({ name, large }: { name: string; large?: boolean }) { return <span className={`grid shrink-0 place-items-center rounded-full bg-[#dcebe4] font-semibold text-[#07533f] ${large ? "size-14" : "size-10 text-sm"}`}>{initials(name)}</span>; }
function Status({ value }: { value: string }) { const good = ["Pago", "Em andamento", "Agendado"].includes(value); return <Badge className={good ? "bg-[#dcf2e6] text-[#087052]" : value === "Parcial" ? "bg-[#fff0d7] text-[#93611a]" : "bg-[#fde4e2] text-[#a74238]"}>{value}</Badge>; }
